function isPowerOfTwo(n) {
  if (n < 1) return false;
  while (n > 1) {
    if (n % 2 !== 0) return false;
    n /= 2;
  }
  return true;
}

console.log(isPowerOfTwo(16));
console.log(isPowerOfTwo(12));
console.log(isPowerOfTwo(1));

